with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.org,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026),u as(select distinct announcement_id from y where std='영구임대'),e as(select announcement_id from y where std='영구임대' and t~'예비예비' union select s.announcement_id from announcement_schedule s join u using(announcement_id) where s.stage_text~'예비예비'),h as(select h.announcement_id,round(h.monthly_rent::numeric/h.area_sqm) v from housing_units h join u using(announcement_id) where h.supply_target~'나군' and h.area_sqm between 26 and 27.99 and h.monthly_rent>0)select json_build_object('anns',(select count(distinct announcement_id) from y where std='영구임대'),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from y where std='영구임대' group by 1)q),'공가발생',(select count(distinct announcement_id) from y where std='영구임대' and t~'공가[^.]{0,30}(발생|생기)'),'공가발생_ex',(select json_agg(i) from(select distinct announcement_id i from y where std='영구임대' and t~'공가[^.]{0,30}(발생|생기)' order by 1 desc limit 3)q),'상당기간',(select count(distinct announcement_id) from y where std='영구임대' and t~'상당\s*(한\s*)?기간'),'상당기간_ex',(select json_agg(i) from(select distinct announcement_id i from y where std='영구임대' and t~'상당\s*(한\s*)?기간' order by 1 desc limit 3)q),'오탈자_예비예비',(select count(distinct announcement_id) from e),'오탈자_예비예비_ex',(select json_agg(i) from(select distinct announcement_id i from e order by 1 desc limit 6)q),'오탈자_아니는',(select count(distinct announcement_id) from y where std='영구임대' and t~'통보하지\s*아니는'),'오탈자_아니는_ex',(select json_agg(i) from(select distinct announcement_id i from y where std='영구임대' and t~'통보하지\s*아니는' order by 1 desc limit 3)q),'나군26_anns',(select count(distinct announcement_id) from h),'나군26_m2',(select json_build_object('min',min(v),'med',round(percentile_cont(0.5)within group(order by v)::numeric),'max',max(v),'ratio',round(max(v)/nullif(min(v),0),2)) from h),'나군26_max_ex',(select json_agg(i) from(select announcement_id||' '||v i from(select distinct on(announcement_id)announcement_id,v from h order by announcement_id,v desc)q0 order by v desc limit 3)q))j;
